کلاس ماشین_حساب {
    عدد ضریب;

    تابع ضرب_کن(عدد مقدار) -> عدد {
        برگردان این.ضریب * مقدار;
    }
}

value.en:
class Calculator {
    int factor;

    func multiply(int value) -> int {
        return this.factor * value;
    }
}

